/**
 * In-memory storage backend for consumer tests.
 *
 * @remarks
 * Swap IndexedDB for memory so a test can assert on stored records without a
 * browser, `fake-indexeddb`, or async timing games:
 *
 * ```ts
 * const repository = createMemoryRepository();
 * initTelemetry({ appName: 'test', repository, shortcut: false });
 * captureError(new Error('boom'));
 * await flushTelemetry();
 * repository.errors.all();      // the stored ErrorRecord
 * ```
 *
 * The semantics intentionally mirror the IndexedDB repositories — pending-only
 * aggregation, atomic claiming, stale-lease requeue, retention cleanup — so a test
 * that passes here is testing real logic, not a stub.
 *
 * @packageDocumentation
 */

import type { Maybe, UploadStatus } from '../core/types.js';
import type { ErrorRecord } from '../errors/types.js';
import type { LogRecord } from '../logger/logger.types.js';
import type {
  CleanupPolicy,
  ErrorRepository,
  LogRepository,
  StorageFailureReason,
  StorageResult,
  TelemetryRepository,
} from '../storage/storage.types.js';

/** Options for {@link createMemoryRepository}. */
export interface MemoryRepositoryOptions {
  /** Make every operation fail with this reason, to exercise degradation paths. */
  readonly failWith?: Maybe<StorageFailureReason>;
  /**
   * Fail writes with `'quota'` once this many rows are stored.
   *
   * @remarks
   * Used to test the quota-recovery path (cleanup with half the cap, then one retry).
   */
  readonly quotaAt?: Maybe<number>;
}

/** Extra inspection helpers layered onto the in-memory repositories. */
export interface InspectableErrorRepository extends ErrorRepository {
  /** Every stored record, newest `lastSeen` first. */
  all(): ErrorRecord[];
  /** Drop everything without touching configuration. */
  reset(): void;
}

/** Extra inspection helpers layered onto the in-memory log repository. */
export interface InspectableLogRepository extends LogRepository {
  /** Every stored record, newest first. */
  all(): LogRecord[];
  /** Drop everything without touching configuration. */
  reset(): void;
}

/** The in-memory backend. */
export interface MemoryRepository extends TelemetryRepository {
  readonly errors: InspectableErrorRepository;
  readonly logs: InspectableLogRepository;
  /** Drop every stored record in both stores. */
  reset(): void;
}

/** Build a success or failure result. */
function result<T>(failure: StorageFailureReason | undefined, value: T): StorageResult<T> {
  return failure === undefined ? { ok: true, value } : { ok: false, reason: failure };
}

/** A record with its `readonly` modifiers stripped, for in-place mutation. */
type Mutable<T> = { -readonly [K in keyof T]: T[K] };

/**
 * Create an in-memory {@link TelemetryRepository}.
 *
 * @param options - see {@link MemoryRepositoryOptions}
 * @returns a fully-featured in-memory backend
 *
 * @example
 * ```ts
 * import { createMemoryRepository } from '@codewithrajat/rm-logvault/testing';
 * import { initTelemetry, captureError, flushTelemetry } from '@codewithrajat/rm-logvault';
 *
 * const repository = createMemoryRepository();
 * initTelemetry({ appName: 'test', repository, shortcut: false });
 *
 * captureError(new Error('boom'));
 * await flushTelemetry();
 *
 * console.log(repository.errors.all()[0]?.message); // 'boom'
 * ```
 */
export function createMemoryRepository(options: MemoryRepositoryOptions = {}): MemoryRepository {
  const errorRows = new Map<string, ErrorRecord>();
  const logRows = new Map<string, LogRecord>();

  /** Decide the failure for a write attempt in a given store. */
  const writeFailure = (size: number): StorageFailureReason | undefined => {
    if (options.failWith !== undefined) return options.failWith;
    if (options.quotaAt !== undefined && size >= options.quotaAt) return 'quota';
    return undefined;
  };

  const cleanup = <T extends { id: string }>(
    rows: Map<string, T>,
    policy: CleanupPolicy,
    timestampOf: (row: T) => number,
  ): number => {
    const now = Date.now();
    const cutoff =
      policy.retentionDays > 0 ? now - policy.retentionDays * 86_400_000 : Number.NEGATIVE_INFINITY;
    let removed = 0;

    for (const [id, row] of [...rows]) {
      if (timestampOf(row) < cutoff) {
        rows.delete(id);
        removed += 1;
      }
    }

    if (policy.maxRecords > 0 && rows.size > policy.maxRecords) {
      const sorted = [...rows.values()].sort((a, b) => timestampOf(a) - timestampOf(b));
      const surplus = sorted.slice(0, rows.size - policy.maxRecords);
      for (const row of surplus) {
        rows.delete(row.id);
        removed += 1;
      }
    }
    return removed;
  };

  const pendingCount = <T extends { uploadStatus: UploadStatus }>(rows: Map<string, T>): number => {
    let total = 0;
    for (const row of rows.values()) {
      if (row.uploadStatus === 'pending' || row.uploadStatus === 'uploading') total += 1;
    }
    return total;
  };

  const errors: InspectableErrorRepository = {
    initialize: async (): Promise<StorageResult<void>> => result(options.failWith, undefined),

    save: async (record: ErrorRecord): Promise<StorageResult<void>> => {
      const failure = writeFailure(errorRows.size);
      if (failure !== undefined) return { ok: false, reason: failure };

      // Pending-only aggregation, matching the IndexedDB repository.
      for (const [id, existing] of errorRows) {
        if (existing.fingerprint === record.fingerprint && existing.uploadStatus === 'pending') {
          errorRows.set(id, {
            ...existing,
            occurrenceCount: existing.occurrenceCount + record.occurrenceCount,
            firstSeen: Math.min(existing.firstSeen, record.firstSeen),
            lastSeen: Math.max(existing.lastSeen, record.lastSeen),
          });
          return { ok: true, value: undefined };
        }
      }
      errorRows.set(record.id, record);
      return { ok: true, value: undefined };
    },

    get: async (id: string): Promise<StorageResult<Maybe<ErrorRecord>>> =>
      result(options.failWith, errorRows.get(id)),

    getAll: async (): Promise<StorageResult<ErrorRecord[]>> =>
      result(
        options.failWith,
        [...errorRows.values()].sort((a, b) => b.lastSeen - a.lastSeen),
      ),

    getPending: async (limit = 100): Promise<StorageResult<ErrorRecord[]>> => {
      const pending = [...errorRows.values()]
        .filter((row) => row.uploadStatus === 'pending')
        .sort((a, b) => b.lastSeen - a.lastSeen);
      return result(options.failWith, limit > 0 ? pending.slice(0, limit) : pending);
    },

    claimPending: async (limit: number, now: number): Promise<StorageResult<ErrorRecord[]>> => {
      const claimed: ErrorRecord[] = [];
      const candidates = [...errorRows.values()]
        .filter((row) => row.uploadStatus === 'pending')
        .sort((a, b) => b.lastSeen - a.lastSeen);
      for (const row of candidates) {
        if (claimed.length >= limit) break;
        const updated: ErrorRecord = {
          ...row,
          uploadStatus: 'uploading',
          uploadAttempts: row.uploadAttempts + 1,
          claimedAt: now,
        };
        errorRows.set(row.id, updated);
        claimed.push(updated);
      }
      return result(options.failWith, claimed);
    },

    requeueStale: async (olderThanMs: number, now: number): Promise<StorageResult<number>> => {
      let requeued = 0;
      for (const [id, row] of [...errorRows]) {
        if (row.uploadStatus !== 'uploading') continue;
        if (row.claimedAt !== undefined && now - row.claimedAt <= olderThanMs) continue;
        const updated: ErrorRecord = { ...row, uploadStatus: 'pending' };
        delete (updated as { claimedAt?: Maybe<number> }).claimedAt;
        errorRows.set(id, updated);
        requeued += 1;
      }
      return result(options.failWith, requeued);
    },

    getFailed: async (): Promise<StorageResult<ErrorRecord[]>> =>
      result(
        options.failWith,
        [...errorRows.values()].filter((row) => row.uploadStatus === 'failed'),
      ),

    delete: async (ids: readonly string[]): Promise<StorageResult<number>> => {
      let removed = 0;
      for (const id of ids) if (errorRows.delete(id)) removed += 1;
      return result(options.failWith, removed);
    },

    updateUploadStatus: async (
      ids: readonly string[],
      status: UploadStatus,
    ): Promise<StorageResult<number>> => {
      let updated = 0;
      for (const id of ids) {
        const row = errorRows.get(id);
        if (row === undefined) continue;
        const next: Mutable<ErrorRecord> = { ...row, uploadStatus: status };
        if (status === 'uploading') next.claimedAt = Date.now();
        else delete next.claimedAt;
        errorRows.set(id, next);
        updated += 1;
      }
      return result(options.failWith, updated);
    },

    count: async (): Promise<StorageResult<number>> => result(options.failWith, errorRows.size),

    pendingCount: async (): Promise<StorageResult<number>> =>
      result(options.failWith, pendingCount(errorRows)),

    cleanup: async (policy: CleanupPolicy): Promise<StorageResult<number>> =>
      result(
        options.failWith,
        cleanup(errorRows, policy, (row) => row.lastSeen),
      ),

    clear: async (): Promise<StorageResult<number>> => {
      const before = errorRows.size;
      errorRows.clear();
      return result(options.failWith, before);
    },

    close: (): void => undefined,

    all: (): ErrorRecord[] => [...errorRows.values()].sort((a, b) => b.lastSeen - a.lastSeen),
    reset: (): void => {
      errorRows.clear();
    },
  };

  const logs: InspectableLogRepository = {
    initialize: async (): Promise<StorageResult<void>> => result(options.failWith, undefined),

    saveBatch: async (records: readonly LogRecord[]): Promise<StorageResult<void>> => {
      const failure = writeFailure(logRows.size);
      if (failure !== undefined) return { ok: false, reason: failure };
      for (const record of records) logRows.set(record.id, record);
      return { ok: true, value: undefined };
    },

    get: async (id: string): Promise<StorageResult<Maybe<LogRecord>>> =>
      result(options.failWith, logRows.get(id)),

    getAll: async (): Promise<StorageResult<LogRecord[]>> =>
      result(
        options.failWith,
        [...logRows.values()].sort((a, b) => b.timestamp - a.timestamp || b.seq - a.seq),
      ),

    getPending: async (limit = 100): Promise<StorageResult<LogRecord[]>> => {
      const pending = [...logRows.values()]
        .filter((row) => row.uploadStatus === 'pending')
        .sort((a, b) => a.timestamp - b.timestamp || a.seq - b.seq);
      return result(options.failWith, limit > 0 ? pending.slice(0, limit) : pending);
    },

    claimPending: async (limit: number, now: number): Promise<StorageResult<LogRecord[]>> => {
      const claimed: LogRecord[] = [];
      const candidates = [...logRows.values()]
        .filter((row) => row.uploadStatus === 'pending')
        .sort((a, b) => a.timestamp - b.timestamp || a.seq - b.seq);
      for (const row of candidates) {
        if (claimed.length >= limit) break;
        const updated: LogRecord = {
          ...row,
          uploadStatus: 'uploading',
          uploadAttempts: row.uploadAttempts + 1,
          claimedAt: now,
        };
        logRows.set(row.id, updated);
        claimed.push(updated);
      }
      return result(options.failWith, claimed);
    },

    requeueStale: async (olderThanMs: number, now: number): Promise<StorageResult<number>> => {
      let requeued = 0;
      for (const [id, row] of [...logRows]) {
        if (row.uploadStatus !== 'uploading') continue;
        if (row.claimedAt !== undefined && now - row.claimedAt <= olderThanMs) continue;
        const updated: LogRecord = { ...row, uploadStatus: 'pending' };
        delete (updated as { claimedAt?: Maybe<number> }).claimedAt;
        logRows.set(id, updated);
        requeued += 1;
      }
      return result(options.failWith, requeued);
    },

    getFailed: async (): Promise<StorageResult<LogRecord[]>> =>
      result(
        options.failWith,
        [...logRows.values()].filter((row) => row.uploadStatus === 'failed'),
      ),

    delete: async (ids: readonly string[]): Promise<StorageResult<number>> => {
      let removed = 0;
      for (const id of ids) if (logRows.delete(id)) removed += 1;
      return result(options.failWith, removed);
    },

    updateUploadStatus: async (
      ids: readonly string[],
      status: UploadStatus,
    ): Promise<StorageResult<number>> => {
      let updated = 0;
      for (const id of ids) {
        const row = logRows.get(id);
        if (row === undefined) continue;
        const next: Mutable<LogRecord> = { ...row, uploadStatus: status };
        if (status === 'uploading') next.claimedAt = Date.now();
        else delete next.claimedAt;
        logRows.set(id, next);
        updated += 1;
      }
      return result(options.failWith, updated);
    },

    count: async (): Promise<StorageResult<number>> => result(options.failWith, logRows.size),

    pendingCount: async (): Promise<StorageResult<number>> =>
      result(options.failWith, pendingCount(logRows)),

    cleanup: async (policy: CleanupPolicy): Promise<StorageResult<number>> =>
      result(
        options.failWith,
        cleanup(logRows, policy, (row) => row.timestamp),
      ),

    clear: async (): Promise<StorageResult<number>> => {
      const before = logRows.size;
      logRows.clear();
      return result(options.failWith, before);
    },

    close: (): void => undefined,

    all: (): LogRecord[] =>
      [...logRows.values()].sort((a, b) => b.timestamp - a.timestamp || b.seq - a.seq),
    reset: (): void => {
      logRows.clear();
    },
  };

  return {
    errors,
    logs,
    initialize: async (): Promise<StorageResult<void>> => result(options.failWith, undefined),
    close: (): void => undefined,
    reset: (): void => {
      errorRows.clear();
      logRows.clear();
    },
  };
}
